 clue(c){const {mesh,box,octa,m,part,step,updates}=c;mesh(box(1.78,.76,1.07),m.wood,0,.51,0);for(const side of[-1,1]){mesh(box(.11,.84,1.14),m.gold,side*.65,.55,0);mesh(box(.22,.12,1.25),m.woodLight,side*.65,.13,0);}const hinge=part('cache-lid');hinge.position.set(0,.91,-.53);mesh(box(1.91,.16,1.16),m.woodLight,0,.02,.53,hinge);mesh(box(.21,.26,.07),m.gold,0,.83,.58);const contents=[];for(let i=0;i<3;i++)contents.push(mesh(octa(.18),m.air,(i-1)*.4,.86,0));updates.push(f=>{hinge.rotation.x=-f*1.05;step(contents,f,(o,p)=>{o.visible=p>0;o.position.y=.76+p*.29;});});},
 'listen-word'(c){const {mesh,cyl,sphere,torus,m,step,updates}=c,flowers=[];for(let i=0;i<3;i++){const g=new T.Group();g.position.set((i-1)*.9,.1,i===1?.37:-.1);c.group.add(g);mesh(cyl(.045,.07,.91,6),m.leaf,0,.46,0,g);const petals=[];for(let j=0;j<5;j++){const a=j*Math.PI*2/5,o=mesh(sphere(.22),i===1?m.pale:m.red,Math.cos(a)*.24,1.0+Math.sin(a)*.24,0,g);o.scale.set(1,.60,.35);o.rotation.z=a;petals.push(o);}const core=mesh(sphere(.15),m.gold,0,1,.10,g);const ring=mesh(torus(.43,.018,Math.PI*1.45),m.air,0,1,-.08,g);flowers.push({petals,core,ring});}updates.push(f=>step(flowers,f,(o,p)=>{o.petals.forEach(x=>{x.scale.z=.25+p*.18;x.rotation.y=(1-p)*.4;});o.core.material=p===1?m.air:m.gold;o.ring.visible=p>0;o.ring.scale.setScalar(.7+p*.4);}));},
