 'listen-multi'(c){const {mesh,box,cyl,sphere,m,step,updates}=c;mesh(box(2.42,.14,.61),m.woodLight,0,1.4,-.46);for(const side of[-1,1])mesh(cyl(.08,.13,1.5,6),m.wood,side*1.08,.84,-.46);owl(c,0,1.42,-.5,.58);const items=[];for(let i=0;i<3;i++){const x=(i-1)*.91;bowl(c,x,.55);const o=mesh(i===1?c.octa(.13):sphere(.13),i===1?m.air:m.fruit,x,1.55,-.44);items.push(o);}updates.push(f=>step(items,f,(o,p,i)=>{o.position.set((i-1)*.91,1.55-p*1.12,-.44+p*.99);o.scale.setScalar(.8+p*.2);}));},
 numbers(c){const {mesh,cyl,box,sphere,m,part,link,step,updates}=c;mesh(cyl(.14,.26,1.45,8),m.wood,0,.83,0);const beam=part('balance-arm');beam.position.y=1.63;mesh(box(2.35,.12,.15),m.woodLight,0,0,0,beam);mesh(sphere(.12),m.gold,0,.08,0,beam);for(const side of[-1,1]){for(const z of[-.23,.23])link([side*.93,-.04,0],[side*.93,-.59,z],.017,m.gold,beam);mesh(cyl(.39,.31,.11,12),m.pale,side*.93,-.63,0,beam);}const weights=[];for(let i=0;i<3;i++)weights.push(mesh(box(.17,.19,.18),m.gold,(i-1)*.25,.23,.83));updates.push(f=>{beam.rotation.z=.16*(1-f);step(weights,f,(o,p,i)=>{o.position.set((i-1)*.25*(1-p)+(-.93+(i-1)*.17)*p,.23+p*.87,.83*(1-p));});});},
 instructions(c){const {mesh,box,cyl,torus,m,part,step,updates}=c;mesh(box(2.46,.14,1.17),m.woodLight,0,.82,0);for(const x of[-1.02,1.02])for(const z of[-.43,.43])mesh(box(.12,.72,.12),m.wood,x,.40,z);const bag=part('packing-bag');bag.position.set(0,.9,-.23);mesh(box(.88,.94,.58),m.leaf,0,.47,0,bag);const flap=mesh(box(.98,.15,.66),m.moss,0,1.03,0,bag);for(const side of[-1,1]){const strap=mesh(torus(.23,.034,Math.PI*1.6),m.woodLight,side*.31,.49,-.31,bag);strap.scale.set(.6,1.5,1);}const items=[];for(let i=0;i<3;i++){const item=mesh(i===1?cyl(.12,.12,.31,9):box(.25,.20,.30),i===1?m.water:i===0?m.pale:m.gold,(i-1)*.69,1.00,.39);items.push(item);}updates.push(f=>{step(items,f,(o,p,i)=>{o.position.set((i-1)*.69*(1-p),1.0+p*.29,.39-p*.62);o.visible=p<1;});flap.rotation.x=-(1-f)*.52;flap.position.y=1.03+(1-f)*.10;});}
