export function makeTrailProp(type,{area=0,completed=false}={}){
 if(!BUILDERS[type])throw new Error('Unknown trail prop type: '+type);
 const c=context(type,area);BUILDERS[type](c);setTrailPropProgress(c.group,completed?1:0);return c.group;
}
export function setTrailPropProgress(group,fraction){
 const state=STATES.get(group);if(!state)return group;
 const f=clamp(fraction);group.userData.progress=f;group.userData.completed=f>=1;
 for(const update of state.updates)update(f);
 return group;
}
